import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import './AdminLoginPage.css';

const AdminLoginPage = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    const result = await login(email, password);

    if (result.success) {
      if (result.user.role === 'admin') {
        navigate('/admin/dashboard');
      } else {
        setError('You do not have admin privileges. Please use the user login page.');
      }
    } else {
      setError(result.error || 'Invalid admin credentials');
    }
  };

  return (
    <div className="admin-login-page">
      <div className="admin-login-container">
        <div className="admin-login-header">
          <i className="fas fa-shield-alt"></i>
          <h2>Admin Login</h2>
          <p>Authorized Personnel Only</p>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Admin Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="admin@strayloveph.org"
              required
            />
          </div>
          <div className="form-group">
            <label>Password</label>
            <input
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              required
            />
          </div>
          <div className="checkbox-group">
            <input
              type="checkbox"
              id="showPassword"
              checked={showPassword}
              onChange={(e) => setShowPassword(e.target.checked)}
            />
            <label htmlFor="showPassword">Show Password</label>
          </div>
          {error && <div className="error-message"><i className="fas fa-exclamation-circle"></i> {error}</div>}
          <button type="submit" className="btn-admin-login">
            <i className="fas fa-sign-in-alt"></i> Login to Admin Panel
          </button>
        </form>
        <div className="back-link">
          <a href="/login"><i className="fas fa-arrow-left"></i> Back to User Login</a>
        </div>
      </div>
    </div>
  );
};

export default AdminLoginPage;
